INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5693953, 826922, 88580, '<td valign="top">Looks rather like a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=74588" rel="nofollow" target="_blank">cutout</a>.  Cool motion in the shoe(s).  Love the texture--I can almost feel it.  The square shapes almost give it a cubist feel.</td>', 'Looks rather like a  cutout.  Cool motion in the shoe(s).  Love the texture--I can almost feel it.  The square shapes almost give it a cubist feel.', '2009-10-20 22:23:28.000000', NULL, 1),
(5693954, 826637, 88580, '<td valign="top">Cyclist is very subtle--seems very distant &amp; conveys the "leaving the frame" concept well.  Great composition--love how the lines lead the eye to the cyclist.</td>', 'Cyclist is very subtle--seems very distant & conveys the "leaving the frame" concept well.  Great composition--love how the lines lead the eye to the cyclist.', '2009-10-20 22:26:54.000000', NULL, 1),
(5693956, 827621, 88580, '<td valign="top">I thought about doing something similar--having an entering and leaving object such that it looked like they were one object that was "wrapping around."  I think this would "read" better if it were flipped--well for those of us who read from left to right, anyway.  Still cool, however.</td>', 'I thought about doing something similar--having an entering and leaving object such that it looked like they were one object that was "wrapping around."  I think this would "read" better if it were flipped--well for those of us who read from left to right, anyway.  Still cool, however.', '2009-10-20 22:32:50.000000', NULL, 1),
(5693960, 827531, 88580, '<td valign="top">A very disorienting image.</td>', 'A very disorienting image.', '2009-10-20 22:34:45.000000', NULL, 1),
(5693965, 827417, 94235, '<td valign="top">That''s what I call taking the challenge literally! Well done and worthy of a ribbon IMO.</td>', 'That''s what I call taking the challenge literally! Well done and worthy of a ribbon IMO.', '2009-10-20 22:38:00.000000', NULL, 1),
(5693968, 827508, 94235, '<td valign="top">Nice clear capture of a hard to get subject in this position. Well done.</td>', 'Nice clear capture of a hard to get subject in this position. Well done.', '2009-10-20 22:39:06.000000', NULL, 1),
